// Fonts rasterised at the display's pixel density and drawn at 1/scale:
// sharp text on Retina instead of a 2x-upscaled bitmap font.
void Gui::loadFonts(float scale) {
  ImGuiIO& io = ImGui::GetIO();
  io.Fonts->Clear();
  ImFontConfig cfg;
  cfg.FontDataOwnedByAtlas = false;
  cfg.OversampleH = 2;
  auto add = [&](const unsigned char* data, size_t size, float px) {
    return io.Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(data), int(size),
                                          px * scale, &cfg);
  };
  fontUi_ = add(kFontUi, kFontUiSize, 15.0f);
  fontBig_ = add(kFontUi, kFontUiSize, 21.0f);
  fontMono_ = add(kFontMono, kFontMonoSize, 13.5f);
  io.FontDefault = fontUi_;
  io.FontGlobalScale = 1.0f / scale;
  dpiScale_ = scale;
}

void Gui::fitWindowToDisplay(int reqW, int reqH) {
  auto* win = static_cast<SDL_Window*>(window_);
  SDL_Rect r{0, 0, 1440, 900};
  SDL_GetDisplayUsableBounds(SDL_GetWindowDisplayIndex(win), &r);
  // The INI default (520x720) predates this layout; anything smaller
  // than a usable size is treated as "pick for me".
  int w = reqW >= 1000 ? reqW : 1400;
  int h = reqH >= 660 ? reqH : 880;
  w = std::min(w, int(r.w * 0.92));
  h = std::min(h, int(r.h * 0.92));
  SDL_SetWindowMinimumSize(win, std::min(980, r.w), std::min(640, r.h));
  SDL_SetWindowSize(win, w, h);
  SDL_SetWindowPosition(win, r.x + (r.w - w) / 2, r.y + (r.h - h) / 2);
}

bool Gui::init(int width, int height) {
  if (SDL_Init(SDL_INIT_VIDEO) != 0) {
    SKW_WARN("gui: SDL_Init failed (%s) - staying headless", SDL_GetError());
    return false;
  }
  auto* win = SDL_CreateWindow("Skywave", SDL_WINDOWPOS_CENTERED,
                               SDL_WINDOWPOS_CENTERED, 1400, 880,
                               SDL_WINDOW_RESIZABLE | SDL_WINDOW_ALLOW_HIGHDPI |
                                   SDL_WINDOW_HIDDEN);
  if (!win) {
    SKW_WARN("gui: window creation failed (%s)", SDL_GetError());
    SDL_Quit();
    return false;
  }
  auto* ren = SDL_CreateRenderer(
      win, -1, SDL_RENDERER_PRESENTVSYNC | SDL_RENDERER_ACCELERATED);
  if (!ren) {
    SKW_WARN("gui: renderer creation failed (%s)", SDL_GetError());
    SDL_DestroyWindow(win);
    SDL_Quit();
    return false;
  }
  window_ = win;
  renderer_ = ren;
  fitWindowToDisplay(width, height);
  SDL_ShowWindow(win);
  IMGUI_CHECKVERSION();
  ImGui::CreateContext();
  ImGuiIO& io = ImGui::GetIO();
  io.IniFilename = nullptr;  // fixed layout: nothing to remember
  applyTheme();
  ImGui_ImplSDL2_InitForSDLRenderer(win, ren);
  ImGui_ImplSDLRenderer2_Init(ren);
  int ww = 1, wh = 1, ow = 1, oh = 1;
  SDL_GetWindowSize(win, &ww, &wh);
  SDL_GetRendererOutputSize(ren, &ow, &oh);
  loadFonts(std::max(1.0f, float(ow) / float(std::max(ww, 1))));

  wfPixels_.assign(size_t(kWfCols) * kWfRows, waterfallLut()[0]);
  wfTexture_ = SDL_CreateTexture(ren, SDL_PIXELFORMAT_ABGR8888,
                                 SDL_TEXTUREACCESS_STREAMING, kWfCols, kWfRows);
  if (wfTexture_) {
    SDL_SetTextureScaleMode(static_cast<SDL_Texture*>(wfTexture_), SDL_ScaleModeLinear);
  }
  wfDirty_ = true;
  fft_ = std::make_unique<Fft>(kSpecFft);

  // Initial widget state: one-time synchronous reads at start-up.
  snprintf(callBuf_, sizeof(callBuf_), "%s", worker_.myCall().c_str());
  const std::string fam = worker_.family();
  for (int i = 0; i < 4; ++i) {
    if (fam == kFamilyNames[i]) familyIdx_ = i;
  }
  monitor_ = worker_.monitoring();
  if (auto u = worker_.feature("ULTRA")) ultraOn_ = *u;
  listenOn_ = worker_.listening();
  cwidOn_ = worker_.cwId();
  maxModeIdx_ = std::clamp(worker_.maxMode() - 4, 0, 9);
  snprintf(pttMethodBuf_, sizeof(pttMethodBuf_), "%s",
           worker_.pttGet("METHOD").c_str());
  snprintf(pttPortBuf_, sizeof(pttPortBuf_), "%s",
           worker_.pttGet("PORT").c_str());
  pttLead_ = atoi(worker_.pttGet("LEAD").c_str());
  pttTail_ = atoi(worker_.pttGet("TAIL").c_str());
  audioDevs_ = listAudioDevices();
  status_ = worker_.status();
  fields_ = parseFields(status_.status);
  ready_ = true;
  return true;
}

