std::optional<std::pair<int, int>> Gui::takeAudioRequest() {
  auto r = audioReq_;
  audioReq_.reset();
  return r;
}

void Gui::noteAudio(const std::string& result) { pushLog("(audio device change)", result); }

void Gui::shutdown() {
  if (!ready_) return;
  if (wfTexture_) SDL_DestroyTexture(static_cast<SDL_Texture*>(wfTexture_));
  wfTexture_ = nullptr;
  ImGui_ImplSDLRenderer2_Shutdown();
  ImGui_ImplSDL2_Shutdown();
  ImGui::DestroyContext();
  SDL_DestroyRenderer(static_cast<SDL_Renderer*>(renderer_));
  SDL_DestroyWindow(static_cast<SDL_Window*>(window_));
  SDL_Quit();
  ready_ = false;
}

// --- waterfall -----------------------------------------------------------------

void Gui::pushWaterfallRow(const std::vector<float>& db) {
  if (wfAutoScale_) {
    // Floor tracks the 15th percentile, ceiling the peak (but at least
    // 30 dB above the floor), both smoothed: structure stays visible on a
    // quiet band and a strong signal does not wash out to white.
    std::vector<float> s(db);
    std::nth_element(s.begin(), s.begin() + long(s.size() * 15 / 100), s.end());
    const float lo = s[s.size() * 15 / 100];
    const float hi = std::max(*std::max_element(db.begin(), db.end()), lo + 30.0f);
    wfFloorDb_ += 0.08f * (lo - 3.0f - wfFloorDb_);
    wfCeilDb_ += 0.08f * (hi - wfCeilDb_);
  }
  const float span = std::max(wfCeilDb_ - wfFloorDb_, 1.0f);
  std::memmove(wfPixels_.data() + kWfCols, wfPixels_.data(),
               sizeof(uint32_t) * size_t(kWfCols) * (kWfRows - 1));
  const auto& lut = waterfallLut();
  for (int c = 0; c < kWfCols; ++c) {
    const float n = std::clamp((db[size_t(c)] - wfFloorDb_) / span, 0.0f, 1.0f);
    wfPixels_[size_t(c)] = lut[size_t(n * 255.0f)];
  }
  wfDirty_ = true;
}

void Gui::pumpSpectrum() {
  if (tap_) {
    float buf[4096];
    size_t n;
    double sq = 0.0;
    size_t cnt = 0;
    while ((n = tap_->read({buf, sizeof(buf) / sizeof(buf[0])})) > 0) {
      tapBuf_.insert(tapBuf_.end(), buf, buf + n);
      for (size_t i = 0; i < n; ++i) sq += double(buf[i]) * buf[i];
      cnt += n;
    }
    if (cnt > 0) {
      const float db = float(10.0 * std::log10(sq / double(cnt) + 1e-12));
      rxMeterDb_ += 0.5f * (db - rxMeterDb_);
      rxMeterHist_.push_back(rxMeterDb_);
      while (rxMeterHist_.size() > 240) rxMeterHist_.pop_front();
    }
    // Stay real time: never fall more than ~2 s of rows behind.
    const size_t cap = size_t(kSpecFft) + size_t(kSpecHop) * 40;
    if (tapBuf_.size() > cap) {
      tapBuf_.erase(tapBuf_.begin(), tapBuf_.begin() + long(tapBuf_.size() - cap));
    }
    static std::vector<float> win;
    if (win.empty()) {
      win.resize(kSpecFft);
      for (int i = 0; i < kSpecFft; ++i) {
        win[size_t(i)] = float(0.5 - 0.5 * std::cos(2.0 * M_PI * i / (kSpecFft - 1)));
      }
    }
    std::vector<cfloat> in(kSpecFft), out(kSpecFft);
    std::vector<float> row(kWfCols);
    const double binHz = double(kFsAudio) / kSpecFft;
    const float norm = 4.0f / float(kSpecFft);  // 2/N, Hann coherent gain 0.5
    while (tapBuf_.size() >= size_t(kSpecFft)) {
      for (int i = 0; i < kSpecFft; ++i) in[size_t(i)] = cfloat(tapBuf_[size_t(i)] * win[size_t(i)], 0.0f);
      fft_->forward(in.data(), out.data());
      for (int c = 0; c < kWfCols; ++c) {
        const int b0 = int(double(c) / kWfCols * wfMaxHz_ / binHz);
        const int b1 = std::max(b0, int(double(c + 1) / kWfCols * wfMaxHz_ / binHz) - 1);
        float best = 0.0f;
        for (int b = b0; b <= b1 && b < kSpecFft / 2; ++b) best = std::max(best, std::abs(out[size_t(b)]));
        row[size_t(c)] = 20.0f * std::log10(best * norm + 1e-9f);
      }
      pushWaterfallRow(row);
      tapBuf_.erase(tapBuf_.begin(), tapBuf_.begin() + kSpecHop);
    }
    return;
  }
  // No tap (file mode, tests): the worker's baseband spectrum.
  if (snap_.spectrumSeq == lastSpectrumSeq_) return;
  lastSpectrumSeq_ = snap_.spectrumSeq;
  std::vector<float> row(kWfCols);
  for (int c = 0; c < kWfCols; ++c) row[size_t(c)] = snap_.spectrumDbfs[c * kSpectrumBins / kWfCols];
  rxMeterDb_ = snap_.rxLevelDbfs;
  pushWaterfallRow(row);
}

void Gui::uploadWaterfall() {
  if (!wfDirty_ || !wfTexture_) return;
  SDL_UpdateTexture(static_cast<SDL_Texture*>(wfTexture_), nullptr, wfPixels_.data(),
                    kWfCols * int(sizeof(uint32_t)));
  wfDirty_ = false;
}

